# ClusterEye Agent - Windows Installer
# Windows counterpart of the Linux install.sh. Designed for UI-driven bootstrap install.
#
# Usage (command generated by the UI):
#   & ([scriptblock]::Create((irm https://archive.clustereye.com/install.ps1))) `
#       -ApiUrl 10.0.0.1:50051 -RegistrationToken eyJ... [-Tls] [-SkipVerify]
#
# The installer no longer writes agent.yml: it runs `clustereye-agent.exe enroll`,
# which stores the endpoint and identity encrypted next to the exe
# (agent-state.enc / agent-secret.enc). The token is never stored. Without
# -ApiUrl/-RegistrationToken the binary and service are installed but the
# service is not started; the enroll command to run is printed instead.
#
# Files: everything lives in the install dir (default
# C:\Program Files\ClusterEyeAgent): the exes, logs\, agent.log, and the
# agent's own files agent-state.enc, agent-secret.enc, agent-conn.key and
# agent-conn.enc (each with an ACL of SYSTEM + Administrators only). An agent
# upgraded from a version <= 1.0.25 also has agent-conn.key / agent-secret.enc
# / agent-conn.enc (and possibly agent-state.enc) in C:\Windows\System32 (the
# service's working directory): the new agent COPIES them into the install dir
# on its first start and leaves the System32 originals in place - restricted
# to SYSTEM + Administrators - so a rollback to the old agent still finds its
# key, secret and cached connection. The install-dir copies are the ones in
# use; the System32 ones are only for that rollback.
#
# Uninstall (elevated PowerShell):
#   Stop-Service ClusterEyeAgent -ErrorAction SilentlyContinue
#   sc.exe delete ClusterEyeAgent        # or: & "C:\Program Files\ClusterEyeAgent\clustereye-agent.exe" -service uninstall
#   Remove-Item "C:\Program Files\ClusterEyeAgent" -Recurse -Force
#   # System32 copies kept for a rollback to an agent <= 1.0.25 (identity and
#   # encrypted credentials; no longer needed once the agent is uninstalled):
#   Remove-Item "$env:SystemRoot\System32\agent-state.enc*", "$env:SystemRoot\System32\agent-secret.enc*",
#       "$env:SystemRoot\System32\agent-conn.key", "$env:SystemRoot\System32\agent-conn.enc*" -Force -ErrorAction SilentlyContinue
# Then remove the agent in the ClusterEye UI so its server-side registration
# and saved connection go too. A later install.ps1 run is a fresh enrollment.

param(
    [string]$Platform = "mssql",
    [string]$ApiUrl = "",
    [string]$RegistrationToken = "",
    [switch]$Tls,
    [switch]$SkipVerify,
    [string]$InstallDir = "C:\Program Files\ClusterEyeAgent",
    # Offline install: path to a pre-downloaded clustereye-agent.exe. When set,
    # the binary is copied locally instead of downloaded from the archive.
    [string]$LocalBinary = "",
    # Version-pinned, verified install. The ClusterEye UI reads these from the
    # release manifest and puts them in the command; when they are present the
    # zip package is installed instead of the bare exe, and nothing lands in
    # $InstallDir until its digest matches.
    [string]$PackageUrl = "",
    [string]$LocalPackage = "",
    [string]$Sha256 = "",
    [string]$Version = ""
)

$ErrorActionPreference = "Stop"

# Windows PowerShell 5.1 does not enable TLS 1.2 by default; the archive is
# served over GitHub Pages (TLS 1.2+). Set it once, up front.
[Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12

$ServiceName = "ClusterEyeAgent"
# Latest agent version is resolved at runtime from the archive release manifest
# (see "Download agent binary" below) - no manual version bump needed.
$ReleasesUrl = "https://archive.clustereye.com/releases.json"

function Write-Step($msg) { Write-Host "`n==> $msg" -ForegroundColor Yellow }
function Write-Ok($msg)   { Write-Host "    $msg" -ForegroundColor Green }
function Write-Fail($msg) { Write-Host "ERROR: $msg" -ForegroundColor Red }

# --- Administrator check ---
$isAdmin = ([Security.Principal.WindowsPrincipal] `
    [Security.Principal.WindowsIdentity]::GetCurrent()
).IsInRole([Security.Principal.WindowsBuiltinRole]::Administrator)
if (-not $isAdmin) {
    Write-Fail "This script must be run as Administrator."
    exit 1
}

# --- Parameter validation ---
# -ApiUrl and -RegistrationToken go together. Neither = manual install: the
# service is installed but not started until the agent is enrolled.
$hasApiUrl = -not [string]::IsNullOrWhiteSpace($ApiUrl)
$hasToken  = -not [string]::IsNullOrWhiteSpace($RegistrationToken)
if ($hasApiUrl -ne $hasToken) {
    Write-Fail "-ApiUrl and -RegistrationToken must be given together."
    exit 1
}
$BootstrapMode = $hasApiUrl -and $hasToken

# Append the default gRPC port (50051) if no port is given.
$GrpcAddress = ""
if ($BootstrapMode) {
    if ($ApiUrl -notmatch ":\d+$") {
        $GrpcAddress = "${ApiUrl}:50051"
    } else {
        $GrpcAddress = $ApiUrl
    }
}

# Note: variable names must NOT case-collide with the [switch] params above
# ($Tls / $SkipVerify) - PowerShell variables are case-insensitive, so a name
# like $skipVerify would overwrite the $SkipVerify switch and break binding.
$tlsValue        = if ($Tls) { "true" } else { "false" }
$hostName        = $env:COMPUTERNAME

Write-Host "ClusterEye Agent installation starting..." -ForegroundColor Yellow
Write-Host "Platform: $Platform"
Write-Host "Install directory: $InstallDir"
if ($BootstrapMode) {
    Write-Host "API address: $GrpcAddress (TLS: $tlsValue)"
} else {
    Write-Host "No -ApiUrl/-RegistrationToken: manual install, the service will not be started."
}

# --- 1. Install directory ---
Write-Step "1. Preparing install directory..."
New-Item -ItemType Directory -Force -Path $InstallDir | Out-Null
# Directory ACL: SYSTEM and Administrators only (full control, inherited by
# everything inside), inheritance from Program Files removed - so
# BUILTIN\Users loses the read access Program Files grants by default.
# Chosen over "Users: ReadAndExecute on the dir": nothing needs non-admin
# access here - the service and the updater run as LocalSystem, the DAM
# worker is its child, and installing/enrolling already requires an elevated
# shell - while Users:RX would leave agent.log, logs\ and agent.yml.migrated
# (redacted, but the host's full configuration) readable by every local user.
# The agent's secret files additionally carry their own protected
# SYSTEM+Administrators ACL (set by the agent on every write), so they stay
# closed even if this directory ACL is later widened (e.g. Explorer's
# "Continue" button adds the browsing admin's account to the directory).
# SIDs, not names: works on localized Windows. Re-applied on every run, so an
# upgrade hardens an existing install; the change propagates to the existing
# files that inherit their ACL.
$aclOut = & icacls.exe $InstallDir /inheritance:r /grant:r "*S-1-5-18:(OI)(CI)F" "*S-1-5-32-544:(OI)(CI)F" 2>&1
if ($LASTEXITCODE -ne 0) {
    # Not fatal: the agent still protects its own files.
    Write-Host "    WARNING: could not restrict the ACL of ${InstallDir}: $aclOut" -ForegroundColor Yellow
} else {
    Write-Ok "$InstallDir access limited to SYSTEM and Administrators"
}
New-Item -ItemType Directory -Force -Path (Join-Path $InstallDir "logs") | Out-Null
Write-Ok "$InstallDir ready"

$ExePath = Join-Path $InstallDir "clustereye-agent.exe"

# --- 2. Stop existing service (idempotent reinstall) ---
$existing = Get-Service -Name $ServiceName -ErrorAction SilentlyContinue
# Remembered so a failed enroll does not leave a previously working agent down.
$wasRunning = [bool]($existing -and $existing.Status -eq "Running")
if ($wasRunning) {
    Write-Step "Stopping existing service..."
    Stop-Service -Name $ServiceName -Force -ErrorAction SilentlyContinue
    Start-Sleep -Seconds 2
}

# --- 3. Provide agent binary (offline: copy local file; online: download) ---
# A package source without a digest would make disabling verification a matter
# of dropping one flag, so the two are required together.
if (($PackageUrl -or $LocalPackage) -and -not $Sha256) {
    Write-Fail "-PackageUrl/-LocalPackage must be used together with -Sha256"
    exit 1
}
if ($PackageUrl -and $LocalPackage) {
    Write-Fail "-PackageUrl and -LocalPackage cannot be used together"
    exit 1
}

# Assert-Sha256 stops the install on a mismatch. It deletes the file and leaves
# any running agent untouched: a failed install must not be a broken one.
function Assert-Sha256([string]$Path, [string]$Expected) {
    $actual = (Get-FileHash -Algorithm SHA256 -Path $Path).Hash
    if ($actual -ine $Expected) {
        # Delete first, report second. If reporting ever grows a side effect
        # that aborts, the unverified file must already be gone.
        Remove-Item -Path $Path -Force -ErrorAction SilentlyContinue
        Write-Fail "Integrity check FAILED - install aborted."
        Write-Host "    expected: $($Expected.ToLower())"
        Write-Host "    actual  : $($actual.ToLower())"
        exit 1
    }
    Write-Ok "SHA-256 verified"
}

if ($PackageUrl -or $LocalPackage) {
    # Package mode. The zip carries ClusterEyeAgentUpdater.exe alongside the
    # agent; installing only the bare exe left every agent unable to self-update,
    # because the updater is looked up in the install dir at update time.
    # It also carries clustereye-dam.exe, the isolated Database Activity
    # Monitoring worker; the agent looks for it next to itself and only runs
    # it when DAM is enabled and licensed. Bare-exe installs report DAM as
    # unavailable ("worker binary not found") rather than failing.
    $stage = Join-Path $env:TEMP ("ce-agent-" + [guid]::NewGuid().ToString("N"))
    New-Item -ItemType Directory -Path $stage -Force | Out-Null
    $pkg = Join-Path $stage "agent-package.zip"
    try {
        if ($LocalPackage) {
            Write-Step "2. Verifying local package: $LocalPackage"
            if (-not (Test-Path $LocalPackage)) { Write-Fail "Local package not found: $LocalPackage"; exit 1 }
            Copy-Item -Path $LocalPackage -Destination $pkg -Force
        } else {
            Write-Step "2. Downloading agent package..."
            if ($Version) { Write-Host "    Version: $Version" }
            Write-Host "    URL: $PackageUrl"
            try {
                Invoke-WebRequest -Uri $PackageUrl -OutFile $pkg -UseBasicParsing
            } catch {
                Write-Fail "Failed to download package: $($_.Exception.Message)"
                Write-Host "    This command is pinned to a version that may have been pruned from the archive."
                Write-Host "    Regenerate the install command from the ClusterEye UI."
                exit 1
            }
        }

        # Before Expand-Archive: extracting an archive is itself an attack surface.
        Assert-Sha256 -Path $pkg -Expected $Sha256

        Write-Step "    Extracting package..."
        Expand-Archive -Path $pkg -DestinationPath $InstallDir -Force
        if (-not (Test-Path $ExePath)) {
            Write-Fail "Package did not contain clustereye-agent.exe"
            exit 1
        }
        Write-Ok "Agent package installed$(if ($Version) { " ($Version)" })"
    } finally {
        Remove-Item -Path $stage -Recurse -Force -ErrorAction SilentlyContinue
    }
} elseif ($LocalBinary) {
    Write-Step "2. Copying local agent binary..."
    if (-not (Test-Path $LocalBinary)) {
        Write-Fail "Local binary not found: $LocalBinary"
        exit 1
    }
    Copy-Item -Path $LocalBinary -Destination $ExePath -Force
    # Verify when a digest was supplied — for an air-gapped install this is the
    # only check the operator gets.
    if ($Sha256) { Assert-Sha256 -Path $ExePath -Expected $Sha256 }
    Write-Ok "clustereye-agent.exe copied from $LocalBinary"
} else {
    Write-Step "2. Downloading agent binary..."
    try {
        $releases = Invoke-RestMethod -Uri $ReleasesUrl -UseBasicParsing
        $AgentVersion = ($releases.agent.releases | Where-Object { $_.latest } | Select-Object -First 1).version
    } catch {
        Write-Fail "Failed to read release manifest ($ReleasesUrl): $($_.Exception.Message)"
        exit 1
    }
    if ([string]::IsNullOrWhiteSpace($AgentVersion)) {
        Write-Fail "Could not determine the latest agent version from releases.json"
        exit 1
    }
    $ExeUrl = "https://archive.clustereye.com/downloads/agent/$AgentVersion/clustereye-agent.exe"
    Write-Host "    Version: $AgentVersion"
    Write-Host "    URL: $ExeUrl"
    try {
        Invoke-WebRequest -Uri $ExeUrl -OutFile $ExePath -UseBasicParsing
    } catch {
        Write-Fail "Failed to download binary: $($_.Exception.Message)"
        exit 1
    }
    Write-Ok "clustereye-agent.exe downloaded ($AgentVersion)"
    Write-Host "    Warning: version not pinned, integrity not verified."
    Write-Host "    Generate the command from the ClusterEye UI for a verified install."
}

# --- 4. Enroll the agent ---
# An agent installed before agent.yml was retired keeps its agent.yml: it is
# neither deleted nor overwritten here; the agent retires it itself once the
# server has acknowledged the new encrypted state.
$ymlPath     = Join-Path $InstallDir "agent.yml"
$statePath   = Join-Path $InstallDir "agent-state.enc"
$existingCfg = (Test-Path $ymlPath) -or (Test-Path $statePath)
if (Test-Path $ymlPath) {
    Write-Host "    Existing agent.yml found; left in place (not overwritten)."
}

# The service was stopped in step 2, so the enroll stream cannot race a
# running agent for its server slot.
$Enrolled = $false
if ($BootstrapMode) {
    Write-Step "3. Enrolling agent..."
    $enrollArgs = @("enroll", "--server", $GrpcAddress, "--token", $RegistrationToken,
                    "--platform", $Platform, "--name", $hostName)
    # -SkipVerify only means something with -Tls (as in the old agent.yml);
    # enroll's --insecure would force TLS onto a plaintext connection.
    if ($Tls) {
        $enrollArgs += "--tls"
        if ($SkipVerify) { $enrollArgs += "--insecure" }
    }

    # Native stderr under ErrorActionPreference=Stop would throw in Windows
    # PowerShell 5.1; capture it as text and judge by the exit code instead.
    $prevEap = $ErrorActionPreference
    $ErrorActionPreference = "Continue"
    Push-Location $InstallDir
    try {
        $enrollOut = & $ExePath @enrollArgs 2>&1 | ForEach-Object { "$_" }
        $enrollRc  = $LASTEXITCODE
    } finally {
        Pop-Location
        $ErrorActionPreference = $prevEap
    }
    if ($enrollOut) { $enrollOut | ForEach-Object { Write-Host "    $_" } }
    if ($enrollRc -ne 0) {
        Write-Fail "Agent enrollment failed (enroll exit code $enrollRc)."
        switch ($enrollRc) {
            2 {
                Write-Host "    This agent is already enrolled with a different API (or the arguments are invalid)."
                $reconf = "& `"$ExePath`" enroll --reconfigure --server $GrpcAddress"
                if ($Tls) {
                    $reconf += " --tls"
                    if ($SkipVerify) { $reconf += " --insecure" }
                }
                Write-Host "    To move the existing registration to this API, run:"
                Write-Host "    $reconf"
            }
            3 { Write-Host "    Could not reach the API: check the address ($GrpcAddress), port and TLS setting." }
            4 { Write-Host "    Registration refused: the token may be invalid or expired; generate a new command in the UI." }
        }
        # A previously running agent keeps running with its existing
        # registration; a fresh install is not started.
        $restored = $false
        if ($wasRunning) {
            Start-Service -Name $ServiceName -ErrorAction SilentlyContinue
            $restored = ((Get-Service -Name $ServiceName -ErrorAction SilentlyContinue).Status -eq "Running")
        }
        if ($restored) {
            Write-Host "    The previously running agent service was restarted with its existing registration." -ForegroundColor Yellow
        } else {
            Write-Host "    The service was not started." -ForegroundColor Red
        }
        exit 1
    }
    $Enrolled = $true
    Write-Ok "Agent enrolled (database connection details set later from the UI)"
} elseif ($existingCfg) {
    Write-Step "3. Keeping existing agent registration..."
    $Enrolled = $true
} else {
    Write-Step "3. Skipping enrollment (no -ApiUrl/-RegistrationToken)..."
}

# --- 5. Install and start the Windows service ---
Write-Step "4. Installing Windows service..."
if ($existing) {
    & $ExePath -service uninstall 2>$null
    Start-Sleep -Seconds 2
}
& $ExePath -platform $Platform -service install
if ($LASTEXITCODE -ne 0) {
    Write-Fail "Service installation failed."
    exit 1
}

# Auto-restart on failure: after a config push the agent exits with a non-zero
# code on purpose; the service manager must bring it back up. Without this the
# service stays Stopped after every database configuration change.
& sc.exe failure $ServiceName reset= 86400 actions= restart/5000/restart/5000/restart/5000 | Out-Null

if (-not $Enrolled) {
    Write-Host "`nInstallation complete; the service was NOT started." -ForegroundColor Green
    Write-Host "1. Enroll the agent (token: ClusterEye UI > Add Agent):"
    Write-Host "   & `"$ExePath`" enroll --server <API_HOST>:50051 --token <TOKEN> --platform $Platform --name $hostName"
    Write-Host "   (add --tls for TLS, --ca-file <ca.pem> for a private CA)"
    Write-Host "2. Start the service:"
    Write-Host "   Start-Service $ServiceName"
    Write-Host "Database connection details: ClusterEye UI > Settings > Agent Runtime"
    exit 0
}

& $ExePath -platform $Platform -service start
if ($LASTEXITCODE -ne 0) {
    Write-Fail "Service failed to start."
    exit 1
}

Write-Host "`nInstallation complete and agent started!" -ForegroundColor Green
Write-Host "The agent is connecting to the ClusterEye API; it will appear in the UI shortly."
Write-Host "Service status:  Get-Service $ServiceName"
Write-Host "Logs:            $InstallDir\logs"
